    public static void main(String[] args) {
        String ageText = "20";
        int age = Integer.parseInt(ageText);     // text into a number
        System.out.println(age + 5);          // 25

        double pi = 3.99;
        System.out.println((int) pi);          // 3, the decimals are simply dropped
        System.out.println(String.valueOf(age));         // a number back into text: "20"
    }
}

